with unpacked as (select id, attributes, try_cast(attributes['weight_kg'] as double) as weight_kg, ship_to.city as ship_city from carts) select ship_city, case when weight_kg >= 4.2 then 'HIGH' else 'LOW' end as weight_kg_tier, round(sum(weight_kg) / nullif(count(case when ship_city = 'Tokyo' then 1 end), 0), 2) as weight_kg_per_tokyo, max(weight_kg) filter (where ship_city = 'Singapore') as singapore_max_weight_kg, round(avg(weight_kg), 2) as avg_weight_kg from unpacked group by ship_city, case when weight_kg >= 4.2 then 'HIGH' else 'LOW' end having weight_kg_per_tokyo >= 0 order by ship_city desc
